digraph "review" {
  start = "build";
  build [kind="activity", label="Build", color="blue"];
  approve [kind="await-signal", label="Approval", shape="diamond"];
  done [kind="complete"];
  denied [kind="fail"];
  build -> approve [on="ok", label="built"];
  build -> denied [on="failed"];
  approve -> done [on="approved"];
  approve -> denied [on="rejected"];
}
